/** Exact bags expose FILTER/input-frame loss independently of any native join strategy. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbFourCycleFilterInputFrameTest {

	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String NS = "urn:four-cycle-input-frame:";
	private static final String PREFIX = "PREFIX : <" + NS + ">\n";
	private static final String RING = "?a :knows ?b . ?b :knows ?c . ?c :knows ?d . ?d :knows ?a .\n";
	private static final List<String> INEQUALITIES = List.of("?a != ?b", "?a != ?c", "?a != ?d",
			"?b != ?c", "?b != ?d", "?c != ?d");
	private static final String CONJUNCTION = String.join(" && ", INEQUALITIES);
	private static final List<String> ROTATIONS = IntStream.range(0, 4)
			.mapToObj(start -> IntStream.range(0, 4)
					.mapToObj(offset -> NS + "n" + ((start + offset) % 4))
					.reduce((left, right) -> left + "|" + right)
					.orElseThrow())
			.sorted()
			.toList();

	@TempDir
	File directory;

	static Stream<Arguments> executionModes() {
		return Stream.of(false, true)
				.flatMap(nativeEnabled -> Stream.of("auto", "exact", "budgeted")
						.map(mode -> Arguments.of(nativeEnabled, mode)));
	}

	static Stream<Arguments> hoistOrientations() {
		return Stream.of(false, true)
				.flatMap(onLeft -> Stream.of(false, true)
						.map(exists -> Arguments.of(onLeft, exists)));
	}

	@ParameterizedTest(name = "gateOnLeft={0}, exists={1}")
	@MethodSource("hoistOrientations")
	void nestedHoistsPreserveBothOperandOrientationsAndTheirRequiredInputs(boolean gateOnLeft, boolean exists) {
		StatementPattern provider = pattern("a", "b");
		Filter consumer = new Filter(pattern("b", "c"),
				new Compare(new Var("a"), new Var("c"), Compare.CompareOp.NE));
		consumer.setRequiredInputBindingNames(Set.of("a"));
		Filter tail = new Filter(pattern("c", "d"),
				new Compare(new Var("b"), new Var("d"), Compare.CompareOp.NE));
		tail.setRequiredInputBindingNames(Set.of("b"));
		String first = gateOnLeft ? "a" : "b";
		String second = gateOnLeft ? "b" : "c";
		ValueExpr condition = exists ? new Exists(pattern(first, second))
				: new Compare(new Var(first), new Var(second), Compare.CompareOp.NE);
		Filter gate = new Filter(gateOnLeft ? provider : consumer, condition);
		var conditionScope = FilterBindingScope.resolve(gate);
		Join inner = new Join(gateOnLeft ? gate : provider, gateOnLeft ? consumer : gate);
		Join outer = new Join(inner, tail);
		QueryRoot root = new QueryRoot(outer);

		new LmdbFilterHoistOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		assertSame(gate, root.getArg(), () -> describe(root));
		assertSame(outer, gate.getArg(), () -> describe(root));
		assertSame(inner, outer.getLeftArg(), () -> describe(root));
		assertSame(tail, outer.getRightArg(), () -> describe(root));
		assertSame(provider, inner.getLeftArg(), () -> describe(root));
		assertSame(consumer, inner.getRightArg(), () -> describe(root));
		assertEquals(conditionScope, FilterBindingScope.resolve(gate), () -> describe(root));
		assertEquals(Set.of("a"), consumer.getRequiredInputBindingNames());
		assertEquals(Set.of("b"), tail.getRequiredInputBindingNames());
		assertEquals(Set.of(), QueryAlgebraBindingAnalysis.withBindingValues(root, EmptyBindingSet.getInstance())
				.requiredInputBindingNames(root), () -> describe(root));
	}

	private static StatementPattern pattern(String subject, String object) {
		return new StatementPattern(new Var(subject),
				new Var("knows", SimpleValueFactory.getInstance().createIRI(NS, "knows")), new Var(object));
	}

	@ParameterizedTest(name = "native={0}, cascades={1}")
	@MethodSource("executionModes")
	void unfilteredRingHasExactlyFourRotations(boolean nativeEnabled, String mode) {
		assertQuery(nativeEnabled, mode, RING, ROTATIONS);
	}

	@ParameterizedTest(name = "native={0}, cascades={1}")
	@MethodSource("executionModes")
	void pairwiseConjunctionRetainsAllRingRotations(boolean nativeEnabled, String mode) {
		assertQuery(nativeEnabled, mode, RING + "FILTER (" + CONJUNCTION + ")", ROTATIONS);
	}

	@ParameterizedTest(name = "native={0}, cascades={1}")
	@MethodSource("executionModes")
	void splitPairwiseFiltersRetainAllRingRotations(boolean nativeEnabled, String mode) {
		String filters = INEQUALITIES.stream()
				.map(condition -> "FILTER (" + condition + ")\n")
				.reduce("", String::concat);
		assertQuery(nativeEnabled, mode, RING + filters, ROTATIONS);
	}

	@ParameterizedTest(name = "native={0}, cascades={1}")
	@MethodSource("executionModes")
	void lateralConditionRetainsItsActualCallerFrame(boolean nativeEnabled, String mode) {
		assertQuery(nativeEnabled, mode, "VALUES ?anchor { :n0 :n2 } LATERAL { " + RING
				+ "FILTER (?a = ?anchor && " + CONJUNCTION + ") }", List.of(ROTATIONS.get(0), ROTATIONS.get(2)));
	}

	@ParameterizedTest(name = "native={0}, cascades={1}")
	@MethodSource("executionModes")
	void optionalUnionAndProjectionPreserveTheCycleBag(boolean nativeEnabled, String mode) {
		String body = "VALUES ?seed { :n0 :n2 } OPTIONAL { "
				+ "{ SELECT ?a ?b ?c ?d WHERE { { " + RING + "FILTER (" + CONJUNCTION + ") } "
				+ "UNION { ?a :knows ?a . } } } FILTER (?a = ?seed) }";
		assertQuery(nativeEnabled, mode, body, List.of(ROTATIONS.get(0), ROTATIONS.get(2)));
	}

	@ParameterizedTest(name = "native={0}, cascades={1}")
	@MethodSource("executionModes")
	void closedProjectionDoesNotAcquireAnOuterConditionBinding(boolean nativeEnabled, String mode) {
		assertQuery(nativeEnabled, mode, "VALUES ?anchor { :n0 } { SELECT ?a ?b ?c ?d WHERE { " + RING
				+ "FILTER (?a = ?anchor && " + CONJUNCTION + ") } }", List.of());
	}

	@ParameterizedTest(name = "native={0}, cascades={1}")
	@MethodSource("executionModes")
	void repeatedVariablePatternDoesNotInventASelfLoop(boolean nativeEnabled, String mode) {
		assertQuery(nativeEnabled, mode, "?a :knows ?a . ?a :knows ?b . ?b :knows ?c . ?c :knows ?d . "
				+ "FILTER (" + CONJUNCTION + ")", List.of());
	}

	private void assertQuery(boolean nativeEnabled, String mode, String body, List<String> expected) {
		String oldNative = System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		String oldMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, mode);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc");
		config.setForceSync(false);
		config.setNativeEvaluationEnabled(true);
		LmdbStore store = new LmdbStore(directory, config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				var vf = connection.getValueFactory();
				IRI knows = vf.createIRI(NS, "knows");
				connection.begin();
				for (int vertex = 0; vertex < 4; vertex++) {
					connection.add(vf.createIRI(NS, "n" + vertex), knows,
							vf.createIRI(NS, "n" + ((vertex + 1) % 4)));
				}
				connection.commit();
				assertEquals(4L, connection.size(), "the reference graph contains exactly the four directed edges");
			}
			String query = PREFIX + "SELECT ?a ?b ?c ?d WHERE { " + body + " }";
			List<String> actual = new ArrayList<>();
			try (var connection = repository.getConnection();
					var rows = connection.prepareTupleQuery(query).evaluate()) {
				while (rows.hasNext()) {
					var row = rows.next();
					actual.add(Stream.of("a", "b", "c", "d")
							.map(name -> row.hasBinding(name) ? row.getValue(name).stringValue() : "UNBOUND")
							.reduce((left, right) -> left + "|" + right)
							.orElseThrow());
				}
			}
			actual.sort(String::compareTo);
			assertEquals(expected, actual, () -> diagnostics(store, repository, query, nativeEnabled, mode));
		} finally {
			try {
				repository.shutDown();
			} finally {
				restore(NATIVE_FLAG, oldNative);
				restore(LmdbCascadesOptimizer.MODE_PROPERTY, oldMode);
			}
		}
	}

	private static String diagnostics(LmdbStore store, SailRepository repository, String query,
			boolean nativeEnabled, String mode) {
		StringBuilder details = new StringBuilder("native=").append(nativeEnabled)
				.append(", cascades=")
				.append(mode)
				.append('\n')
				.append(query);
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		details.append("\nParsed:\n").append(describe(parsed));
		// Replay only the normalizer prefix against the same store's real read source. The selected plan below
		// still comes from the repository's unchanged production optimizer/evaluator route.
		try (SailDataset dataset = store.getBackingStore()
				.getExplicitSailSource()
				.dataset(IsolationLevels.SNAPSHOT_READ)) {
			SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
			EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
			EvaluationStrategy strategy = store.getConnectionEvaluationStrategyFactory()
					.createEvaluationStrategy(
							null, source, statistics, store.getQueryExecutionPolicy());
			for (QueryOptimizer optimizer : new LmdbQueryOptimizerPipeline(strategy, source, statistics)
					.getOptimizers()) {
				if (optimizer instanceof LmdbCascadesOptimizer) {
					break;
				}
				optimizer.optimize(parsed, null, EmptyBindingSet.getInstance());
				details.append("\nAfter ")
						.append(optimizer.getClass().getSimpleName())
						.append(":\n")
						.append(describe(parsed));
			}
		}
		try (var connection = repository.getConnection()) {
			TupleExpr optimized = (TupleExpr) connection.prepareTupleQuery(query)
					.explain(Explanation.Level.Optimized)
					.tupleExpr();
			details.append("\nActual optimized repository plan:\n").append(describe(optimized));
		}
		return details.toString();
	}

	private static String describe(TupleExpr expression) {
		StringBuilder details = new StringBuilder(expression.toString());
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				details.append("\nFILTER condition=")
						.append(filter.getCondition())
						.append(" declared=")
						.append(filter.getConditionBindingScope())
						.append(" resolved=")
						.append(FilterBindingScope.resolve(filter))
						.append(" requiredInputs=")
						.append(filter.getRequiredInputBindingNames())
						.append(" scopeChange=")
						.append(filter.isVariableScopeChange());
				super.meet(filter);
			}

			@Override
			public void meet(Join join) {
				details.append("\nJOIN algorithm=")
						.append(join.getAlgorithmName())
						.append(" left=")
						.append(join.getLeftArg().getBindingNames())
						.append(" right=")
						.append(join.getRightArg().getBindingNames())
						.append(" nativePath=")
						.append(join.getStringMetricActual("nativeExecutionPath"))
						.append(" hint=")
						.append(join.getStringMetricPlanned("optimizer.joinAlgorithmHint"));
				super.meet(join);
			}
		});
		return details.append('\n').toString();
	}

	private static void restore(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}
}
